mapper.select:
SELECT COUNT(*)
FROM medical_dept md
WHERE 1 = 1

    AND name LIKE CONCAT('%',#{name},'%')


    AND outpatient = #{outpatient}


    AND recommended = #{recommended}

SELECT d.id AS id, d.name AS name, d.outpatient AS outpatient, d.recommended AS recommended, t1.subs AS subs, t2.doctors AS doctors, d.description AS description FROM medical_dept d JOIN ( SELECT md.id, COUNT(ms.id) AS subs FROM medical_dept md LEFT JOIN medical_dept_sub ms ON ms.dept_id = md.id GROUP BY md.id ) t1 ON t1.id = d.id JOIN ( SELECT md.id, COUNT(d.id) AS doctors FROM medical_dept md LEFT JOIN medical_dept_sub ms ON ms.dept_id = md.id LEFT JOIN medical_dept_sub_doctor sd ON sd.dept_sub_id = ms.id LEFT JOIN doctor d ON d.id = sd.doctor_id AND d.status = 1 GROUP BY md.id ) t2 ON d.id = t2.id WHERE 1 = 1
AND name LIKE CONCAT('%',#{name},'%')
AND outpatient = #{outpatient}
AND recommended = #{recommended}
LIMIT #{length} OFFSET #{start}

SELECT name,description,outpatient,recommended
FROM medical_dept md
WHERE md.id = #{id}

